def record_expense(trip_id: str, expense: Expense) -> Trip:
    repo = yield from need(TripRepository)
    trip = repo.load_trip(trip_id)
    if trip.closed:
        return (yield from throw(ClosedTripError(trip_id)))

    error = validate_trip_configuration(trip)
    if error is not None:
        return (yield from throw(ValidationError(error)))

    error = validate_expense(expense, trip)
    if error is not None:
        return (yield from throw(ValidationError(error)))

    error = validate_new_action(trip, ExpenseAction(expense))
    if error is not None:
        return (yield from throw(ValidationError(error)))

    new_trip = append_action(trip, ExpenseAction(expense))
    repo.save_trip(new_trip)
    return new_trip

